    echo '{"session_id":"s1","agent_name":"test","repo_path":"/repo","session_ref":"ref"}'
    ;;
  write-session)
    exit 0
    ;;
  format-resume-command)
    echo '{"command": "test-agent resume '$3'"}'
    ;;
  read-transcript)
    echo 'raw transcript data'
    ;;
  chunk-transcript)
    echo '{"chunks": ["Y2h1bms="]}'
    ;;
  reassemble-transcript)
    cat
    ;;
  parse-hook)
    echo 'null'
    ;;
  install-hooks)
    echo '{"hooks_installed": 2}'
    ;;
  uninstall-hooks)
    exit 0
    ;;
  are-hooks-installed)
    echo '{"installed": true}'
    ;;
