func TestRun_AppliesTimeoutWhenNoDeadline(t *testing.T) {
	// Not parallel: mutates package-level defaultRunTimeout.
	if _, err := exec.LookPath("sh"); err != nil {
		t.Skip("sh not available")
	}

	script := `#!/bin/sh
